package cn.zhuatech.reportagent.controller; import cn.zhuatech.reportagent.common.ApiResponse; import cn.zhuatech.reportagent.dto.ReportAgentDto.*; import cn.zhuatech.reportagent.service.ReportAgentService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOMAIN_OPERATOR','QUALITY','ADMIN')") public class OperationsAdminController {private final ReportAgentService service;public OperationsAdminController(ReportAgentService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkRecordView>> orders(){return ApiResponse.ok(service.workRecords());}}
